// Browser (and Node) mirror of slide_generator.rb: deck normalization, markdown, and the six
// templates in templates/*.html.erb. test/site_test.rb renders the same slides through both
// and requires identical pixels, so change the two together.
//
// Data (styles.css, catalog, brands) comes from engine-data.js, generated by `rake slides:site`.
(function (root, factory) {
  if (typeof module !== 'undefined') module.exports = factory();
  else root.SlidesEngine = factory();
})(typeof self !== 'undefined' ? self : this, function () {
  'use strict';

  const blank = (v) => v === undefined || v === null || (typeof v === 'string' && v.trim() === '');
  const isHash = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);

  function escapeHtml(value) {
    return String(value)
      .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;').replace(/'/g, '&#39;');
  }

  // ---- Deck normalization (SlideGenerator#normalize_deck_config / #normalize_slide) ----

  function valueForAliases(aliases, slide, rawContent) {
    for (const key of aliases) {
      if (key === 'content' && typeof slide.content === 'string') return slide.content;
      if (key in slide && !blank(slide[key])) {
        if (key === 'content' && isHash(slide[key])) continue;
        return slide[key];
      }
      if (key in rawContent && !blank(rawContent[key])) return rawContent[key];
    }
    return null;
  }

  function normalizeSlide(slide, engine) {
    const templateName = String(slide.template || slide.type || '');
    if (!templateName) throw new Error('Missing "template" in slide: ' + JSON.stringify(slide).slice(0, 120));
    const spec = engine.templates[templateName];
    if (!spec) throw new Error(`Unknown template "${templateName}". Known: ${Object.keys(engine.templates).join(', ')}`);

    const rawContent = isHash(slide.content) ? slide.content : {};
    const payload = {};
    for (const [renderKey, aliases] of Object.entries(spec.field_aliases || {})) {
      const value = valueForAliases(aliases, slide, rawContent);
      if (!blank(value)) payload[renderKey] = value;
    }

    const normalized = {
      type: templateName,
      title: payload.title, subtitle: payload.subtitle, heading: payload.heading,
      content: payload.content, left: payload.left, right: payload.right,
      image: payload.image, image_prompt: payload.image_prompt, notes: slide.notes
    };
    const missing = (spec.required_fields || []).filter((field) =>
      field === 'image' && !blank(normalized.image_prompt) ? false : blank(normalized[field]));
    return { slide: normalized, missing };
  }

  function deckConfig(data, engine) {
    const deck = isHash(data) && isHash(data.deck) ? data.deck : {};
    const top = isHash(data) ? data : {};
    const canvas = Object.assign({}, deck.canvas || {}, top.canvas || {});
    const width = canvas.width || engine.canvas.width;
    const height = canvas.height || engine.canvas.height;

    const brandKey = top.brand || deck.brand || null;
    const brand = brandKey ? engine.brands[brandKey] : null;
    if (brandKey && !brand) throw new Error(`Unknown brand "${brandKey}". Available: ${Object.keys(engine.brands).join(', ')}`);

    const deckTheme = Object.assign({}, deck.theme || {}, top.theme || {});
    const unknown = Object.keys(deckTheme).filter((k) => !(k in engine.themeDefaults));
    if (unknown.length) throw new Error(`Unknown theme token(s): ${unknown.join(', ')}`);

    const theme = Object.assign({}, brand ? brand.theme : {}, deckTheme);
    theme.slide_width = `${width}px`;
    theme.slide_height = `${height}px`;
    return { title: deck.title, theme, brand, canvas: { width, height } };
  }

  // Returns { config, slides: [{ slide, missing }] }; throws on unknown brand/template/token.
  function normalizeDeck(data, engine) {
    const slides = Array.isArray(data) ? data : data && data.slides;
    if (!Array.isArray(slides)) throw new Error('Deck must be an array of slides or an object with "slides"');
    return { config: deckConfig(Array.isArray(data) ? {} : data, engine), slides: slides.map((s) => normalizeSlide(s, engine)) };
  }

  // ---- Styles and helpers (BindingContext) ----

  function styles(config, engine) {
    const imports = ((config.brand && config.brand.fonts) || []).map((url) => `@import url("${url}");`).join('\n');
    const vars = Object.entries(config.theme || {})
      .filter(([, v]) => v !== null && v !== undefined)
      .map(([k, v]) => `--${k.replace(/_/g, '-')}: ${v};`);
    const override = vars.length ? `:root {\n  ${vars.join('\n  ')}\n}` : '';
    return [imports, engine.stylesCss, override].filter((part) => part !== '').join('\n');
  }

  function tableHtml(rows) {
    const cells = rows.map((row) => {
      const parts = row.trim().replace(/^\|/, '').replace(/\|$/, '').split('|');
      while (parts.length && parts[parts.length - 1] === '') parts.pop(); // Ruby String#split drops trailing empties
      return parts.map((cell) => cell.trim());
    }).filter((row) => !row.every((cell) => /^:?-{3,}:?$/.test(cell)));
    const [header, ...body] = cells;

    const html = ['<table>', '  <thead>', '    <tr>'];
    (header || []).forEach((cell) => html.push(`      <th>${cell}</th>`));
    html.push('    </tr>', '  </thead>', '  <tbody>');
    body.forEach((row) => {
      html.push('    <tr>');
      row.forEach((cell) => html.push(`      <td>${cell}</td>`));
      html.push('    </tr>');
    });
    html.push('  </tbody>', '</table>');
    return html.join('\n');
  }

  function markdown(text) {
    if (!text) return '';
    text = String(text)
      .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
      .replace(/\*(.+?)\*/g, '<em>$1</em>')
      .replace(/`(.+?)`/g, '<code>$1</code>');

    let inList = false;
    let tableRows = [];
    const result = [];
    for (const line of text.split('\n')) {
      if (line.trim().startsWith('|')) {
        if (inList) result.push('</ul>');
        inList = false;
        tableRows.push(line);
        continue;
      } else if (tableRows.length) {
        result.push(tableHtml(tableRows));
        tableRows = [];
      }

      const stripped = line.trim();
      if (stripped.startsWith('- ') || stripped.startsWith('* ')) {
        if (!inList) result.push('<ul>');
        inList = true;
        result.push(`  <li>${stripped.replace(/^[-*]\s+/, '')}</li>`);
      } else {
        if (inList) result.push('</ul>');
        inList = false;
        if (stripped !== '') result.push(`<p>${line}</p>`);
      }
    }
    if (inList) result.push('</ul>');
    if (tableRows.length) result.push(tableHtml(tableRows));
    return result.join('\n');
  }

  function brandMark(config) {
    const brand = config.brand;
    if (!brand || !(brand.logo || brand.mark)) return '';
    const parts = [];
    if (brand.logo) parts.push(`<img\n  src="${brand.logo}"\n  alt=""\n>`);
    if (brand.mark) parts.push(`<span>${escapeHtml(brand.mark)}</span>`);
    return `<div\n  class="brand-mark"\n>\n${parts.join('\n')}\n</div>`;
  }

  // ---- Templates (templates/*.html.erb) ----

  const page = (css, body) => `<!DOCTYPE html>
<html>
<head>
  <meta
    charset="UTF-8"
  >
  <style>${css}</style>
</head>
<body>
${body}
</body>
</html>`;

  const number = (n) => `    <div
      class="slide-number"
    >${n}</div>`;

  const TEMPLATES = {
    title: (s, n, mark) => `  <div
    class="slide title"
  >
    <h1>${s.title}</h1>
${s.subtitle ? `      <div
        class="subtitle"
      >${s.subtitle}</div>` : ''}
    ${mark}
${number(n)}
  </div>`,

    section: (s, n, mark) => `  <div
    class="slide section"
  >
    <h2>${s.heading}</h2>
    ${mark}
${number(n)}
  </div>`,

    normal: (s, n, mark) => `  <div
    class="slide normal"
  >
${s.title ? `      <h2>${s.title}</h2>` : ''}
    <div
      class="content"
    >
      ${markdown(s.content)}
    </div>
    ${mark}
${number(n)}
  </div>`,

    two_column: (s, n, mark) => `  <div
    class="slide two_column"
  >
${s.title ? `      <h2>${s.title}</h2>` : ''}
    <div
      class="columns"
    >
      <div
        class="column"
      >
        ${markdown(s.left)}
      </div>
      <div
        class="column"
      >
        ${markdown(s.right)}
      </div>
    </div>
    ${mark}
${number(n)}
  </div>`,

    content_image: (s, n, mark) => `  <div
    class="slide content_image"
  >
${s.title ? `      <h2>${s.title}</h2>` : ''}
    <div
      class="columns"
    >
      <div
        class="column text"
      >
        ${markdown(s.content)}
      </div>
      <div
        class="column image"
      >
        <img
          src="${s.image || ''}"
          alt=""
        >
      </div>
    </div>
    ${mark}
${number(n)}
  </div>`,

    full_image: (s, n, mark) => `  <div
    class="slide full_image"
  >
    <img
      src="${s.image || ''}"
      alt=""
    >
${s.title ? `      <div
        class="caption"
      >${s.title}</div>` : ''}
    ${mark}
${number(n)}
  </div>`
  };

  // Full HTML document for one normalized slide.
  function renderSlide(slide, slideNumber, config, engine) {
    const template = TEMPLATES[slide.type];
    if (!template) throw new Error(`No browser template for "${slide.type}"`);
    return page(styles(config, engine), template(slide, slideNumber, brandMark(config)));
  }

  return { normalizeDeck, normalizeSlide, deckConfig, renderSlide, markdown, styles, escapeHtml, TEMPLATES };
});
